package servers

import (
	"context"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"errors"
	"slices"
	"strings"

	"github.com/sorrelfox/postsonde/internal/core/appsecrets"
	"github.com/sorrelfox/postsonde/internal/core/errs"
	"github.com/sorrelfox/postsonde/internal/core/fileaccess"
	core "github.com/sorrelfox/postsonde/internal/core/servers"
	"github.com/sorrelfox/postsonde/internal/core/servers/servertls"
	"github.com/sorrelfox/postsonde/internal/core/tlsconf"
)

// Local TLS (SRV-05, docs/servers.md#tls): a server serves TLS with a
// certificate generated by the local CA of the data directory
// (servertls) or with the user's certificate files. The definition holds
// the file paths only; a passphrase is kept in the app's local secret
// storage (appsecrets, per file) and never leaves Go. Create, UpdateServer
// and CreateFolderServer read the files when they are set, so a bad file
// or passphrase is an error at once, not at start.

// Error codes of local TLS in the service.
const (
	// CodeTLSFileKind: PickTLSFile got a kind other than "cert", "key" or
	// "pfx".
	CodeTLSFileKind = "servers.tls_file_kind"
	// CodeRevealUnavailable: RevealLocalCA cannot show a file manager.
	CodeRevealUnavailable = "servers.reveal_unavailable"
)

// ServerTLSDTO is how a server serves TLS, null for plain text.
type ServerTLSDTO struct {
	// Certificate is "generated" (the local CA's) or "files".
	Certificate string `json:"certificate"`
	// CertFile and KeyFile (PEM) or PFXFile (PKCS#12): absolute paths.
	CertFile string `json:"certFile"`
	KeyFile  string `json:"keyFile"`
	PFXFile  string `json:"pfxFile"`
	// HasPassphrase is true when a passphrase is stored for the file.
	HasPassphrase bool `json:"hasPassphrase"`
}

// ServerTLSInputDTO sets how a server serves TLS; null serves plain text.
type ServerTLSInputDTO struct {
	Certificate string `json:"certificate"`
	CertFile    string `json:"certFile"`
	KeyFile     string `json:"keyFile"`
	PFXFile     string `json:"pfxFile"`
	// Passphrase of the PKCS#12 file or of an encrypted PKCS#8 key. Null
	// keeps the one stored for the file, "" removes it.
	Passphrase *string `json:"passphrase"`
}

// ServerCertDTO describes the certificate a running TLS server presents.
type ServerCertDTO struct {
	Subject string `json:"subject"`
	Issuer  string `json:"issuer"`
	// NotBefore and NotAfter are RFC 3339 in UTC.
	NotBefore string `json:"notBefore"`
	NotAfter  string `json:"notAfter"`
	// SHA256 is the fingerprint, lower-case hex.
	SHA256 string `json:"sha256"`
	// Names are the DNS names and IP addresses it is valid for.
	Names []string `json:"names"`
}

// LocalCADTO describes the local CA that signs generated certificates.
type LocalCADTO struct {
	// Path is ca.pem in the data directory, "" when the CA is kept in
	// memory (no data directory).
	Path     string `json:"path"`
	Subject  string `json:"subject"`
	NotAfter string `json:"notAfter"`
	SHA256   string `json:"sha256"`
	PEM      string `json:"pem"`
	// Trusted is true when Path is one of the CA bundles PostSonde's
	// clients trust (Settings, Network).
	Trusted bool `json:"trusted"`
}

// WithTLS sets the local CA of generated certificates and the storage of
// certificate passphrases. Without it both are kept in memory for the
// session.
func WithTLS(ca *servertls.Authority, secrets *appsecrets.Store) Option {
	return func(s *ServersService) { s.ca, s.secrets = ca, secrets }
}

// WithTrustedBundles tells LocalCA which CA bundles the app's clients
// trust, to say whether the local CA is one of them.
func WithTrustedBundles(bundles func() []string) Option {
	return func(s *ServersService) { s.bundles = bundles }
}

// WithReveal sets how RevealLocalCA shows a file in the file manager.
func WithReveal(reveal func(path string) error) Option {
	return func(s *ServersService) { s.reveal = reveal }
}

// initTLS fills in the defaults of WithTLS and returns the certificate
// source of the Manager.
func (s *ServersService) initTLS() core.CertificateSource {
	if s.ca == nil {
		s.ca = servertls.NewAuthority("")
	}
	if s.secrets == nil {
		s.secrets = appsecrets.New("")
	}
	p := &servertls.Provider{CA: s.ca, Passphrase: s.passphrase, CheckFiles: s.checkTLSFiles}
	return p.Source()
}

// checkTLSFiles refuses the certificate files of t outside the project
// folder and the allowed directories (PRV-10): a server definition is
// project data, and serving a file is sending it.
func (s *ServersService) checkTLSFiles(t core.TLS) error {
	p := s.filePolicy()
	p.Subject = "The server certificate file"
	for _, f := range []struct{ field, path string }{{"certFile", t.CertFile}, {"keyFile", t.KeyFile}, {"pfxFile", t.PFXFile}} {
		if f.path == "" {
			continue
		}
		if _, err := p.Resolve(f.path); fileaccess.IsNotAllowed(err) {
			e, _ := errors.AsType[*errs.Error](err)
			return e.WithDetail("field", f.field)
		}
	}
	return nil
}

func (s *ServersService) passphrase(file string) (string, error) {
	return s.secrets.Get(appsecrets.ServerCertPassphraseKey(file))
}

// toCore returns the TLS of in and the passphrase to store for its file
// (nil: keep the stored one).
func (in *ServerTLSInputDTO) toCore() (*core.TLS, *string) {
	if in == nil {
		return nil, nil
	}
	t := &core.TLS{
		Certificate: strings.TrimSpace(in.Certificate),
		CertFile:    strings.TrimSpace(in.CertFile),
		KeyFile:     strings.TrimSpace(in.KeyFile),
		PFXFile:     strings.TrimSpace(in.PFXFile),
	}
	if t.Certificate != core.CertFiles {
		t.CertFile, t.KeyFile, t.PFXFile = "", "", ""
		return t, nil
	}
	return t, in.Passphrase
}

// checkTLS reads the certificate files of t with pass (nil: the stored
// passphrase), so a bad file or passphrase fails the save.
func (s *ServersService) checkTLS(t *core.TLS, pass *string) error {
	if t == nil || t.Certificate != core.CertFiles {
		return nil
	}
	if err := s.checkTLSFiles(*t); err != nil {
		return err
	}
	p := ""
	if pass != nil {
		p = *pass
	} else {
		stored, err := s.passphrase(servertls.SecretFile(*t))
		if err != nil {
			return err
		}
		p = stored
	}
	_, err := tlsconf.LoadServerCert(t.CertFile, t.KeyFile, t.PFXFile, p)
	return err
}

// storePassphrase keeps pass for the file of t; nil keeps what is stored.
func (s *ServersService) storePassphrase(t *core.TLS, pass *string) error {
	if t == nil || t.Certificate != core.CertFiles || pass == nil {
		return nil
	}
	return s.secrets.Set(appsecrets.ServerCertPassphraseKey(servertls.SecretFile(*t)), *pass)
}

// prepareTLS turns in into the TLS of a definition and checks it.
func (s *ServersService) prepareTLS(in *ServerTLSInputDTO) (*core.TLS, *string, error) {
	t, pass := in.toCore()
	if err := s.checkTLS(t, pass); err != nil {
		return nil, nil, err
	}
	return t, pass, nil
}

func toTLSDTO(t *core.TLS) *ServerTLSDTO {
	if t == nil {
		return nil
	}
	return &ServerTLSDTO{Certificate: t.Certificate, CertFile: t.CertFile, KeyFile: t.KeyFile, PFXFile: t.PFXFile}
}

// serverDTO is toServerDTO with whether a passphrase is stored for the
// server's certificate file.
func (s *ServersService) serverDTO(srv core.Server) ServerDTO {
	dto := toServerDTO(srv)
	if t := srv.Spec.TLS; t != nil && t.Certificate == core.CertFiles {
		if p, err := s.passphrase(servertls.SecretFile(*t)); err == nil && p != "" {
			dto.TLS.HasPassphrase = true
		}
	}
	return dto
}

func (s *ServersService) serverDTOs(list []core.Server) []ServerDTO {
	out := make([]ServerDTO, 0, len(list))
	for _, srv := range list {
		out = append(out, s.serverDTO(srv))
	}
	return out
}

func toCertDTO(c *x509.Certificate) *ServerCertDTO {
	if c == nil {
		return nil
	}
	sum := sha256.Sum256(c.Raw)
	dto := &ServerCertDTO{
		Subject:   c.Subject.String(),
		Issuer:    c.Issuer.String(),
		NotBefore: formatTime(c.NotBefore),
		NotAfter:  formatTime(c.NotAfter),
		SHA256:    hex.EncodeToString(sum[:]),
		Names:     slices.Clone(c.DNSNames),
	}
	if dto.Names == nil {
		dto.Names = []string{}
	}
	for _, ip := range c.IPAddresses {
		dto.Names = append(dto.Names, ip.String())
	}
	return dto
}

// PickTLSFile shows the native file dialog for a server certificate file
// and returns the chosen absolute path, "" when the user cancels. kind is
// "cert" (PEM certificate), "key" (PEM private key) or "pfx" (PKCS#12).
func (s *ServersService) PickTLSFile(ctx context.Context, kind string) (string, error) {
	if err := interrupted(ctx, "Choosing a file"); err != nil {
		return "", err
	}
	var d FileDialog
	switch kind {
	case "cert":
		d = FileDialog{Title: "Choose the server certificate", Message: "Choose a PEM file with the server certificate (and any intermediates after it).",
			ButtonText: "Choose", FilterName: "PEM certificates (*.pem, *.crt, *.cer)", FilterPattern: "*.pem;*.crt;*.cer"}
	case "key":
		d = FileDialog{Title: "Choose the private key", Message: "Choose the PEM private key of the server certificate.",
			ButtonText: "Choose", FilterName: "PEM keys (*.key, *.pem)", FilterPattern: "*.key;*.pem"}
	case "pfx":
		d = FileDialog{Title: "Choose the PKCS#12 file", Message: "Choose a .p12 or .pfx file with the server certificate and its key.",
			ButtonText: "Choose", FilterName: "PKCS#12 files (*.p12, *.pfx)", FilterPattern: "*.p12;*.pfx"}
	default:
		return "", errs.New(errs.InvalidArgument, "Unknown kind of certificate file "+kind+".").WithCode(CodeTLSFileKind)
	}
	if s.pick == nil {
		return "", errs.New(errs.Unsupported, "Choosing a file is not available here.").WithCode(CodePickUnavailable)
	}
	path, err := s.pick(ctx, d)
	if err != nil {
		return "", errs.Wrap(err, errs.KindOf(err), "The file dialog could not be shown.").WithCode(CodePickUnavailable)
	}
	return path, nil
}

// LocalCA returns the local CA that signs generated certificates,
// creating it in the data directory the first time.
func (s *ServersService) LocalCA(ctx context.Context) (LocalCADTO, error) {
	if err := interrupted(ctx, "Loading the local CA"); err != nil {
		return LocalCADTO{}, err
	}
	ca, err := s.ca.CA()
	if err != nil {
		return LocalCADTO{}, err
	}
	dto := LocalCADTO{Path: ca.Path, Subject: ca.Cert.Subject.String(), NotAfter: formatTime(ca.Cert.NotAfter), SHA256: ca.SHA256(), PEM: string(ca.PEM)}
	if s.bundles != nil && ca.Path != "" {
		dto.Trusted = slices.Contains(s.bundles(), ca.Path)
	}
	return dto, nil
}

// RevealLocalCA shows the local CA's certificate file in the file
// manager.
func (s *ServersService) RevealLocalCA(ctx context.Context) error {
	ca, err := s.LocalCA(ctx)
	if err != nil {
		return err
	}
	if s.reveal == nil || ca.Path == "" {
		return errs.New(errs.Unsupported, "The file cannot be shown here.").WithCode(CodeRevealUnavailable)
	}
	if err := s.reveal(ca.Path); err != nil {
		return errs.Wrap(err, errs.KindOf(err), "The file manager could not be opened.").WithCode(CodeRevealUnavailable)
	}
	return nil
}
